		{"reported zero", sortRow("a", "x", "k", 0, true), 0},
		{"some", sortRow("a", "x", "k", 42, true), 42},
	}
	for _, c := range cases {
		if got := starsKey(c.row); got != c.want {
			t.Errorf("%s: starsKey = %d, want %d", c.name, got, c.want)
		}
	}
}

